  ["eb32eb44ff081d85"] = { "La gente pensa che i corn dog mi piacciano, ma in realtà mi fanno venire l'indigestione!!!", "." },
  ["eb387e5c80299896"] = { "Come?? Be', è una lunga storia.", "." },
  ["eb39dca045ca01fd"] = { "Molto bene, {name}! Ascolta e impara.\n\nLa forgiatura non nasce mai da qui! <Hank indica il suo martello.>\n\nLa forgiatura non nasce mai da qui! <Hank indica l'incudine.>\n\nLa forgiatura nasce solo da qui! <Hank indica il suo cuore.>\n\nE ora conosci l'origine della forgiatura.", "." },
  ["eb3a1fa3f9d4387c"] = { "Con i recenti attacchi intorno al ⟦Lake Al'Ameth=Lago Al'ameth⟧, tutti i pescatori si sono trasferiti a Darnassus. Dovresti cercare lì qualcuno che ti addestri.", "." },
  ["eb3c195ffff8d030"] = { "Grazie, gentile <straniero/straniera>. Che il tuo eroismo non venga mai dimenticato.", "." },
  ["eb41a991fbf9b540"] = { "Il vilsegugio... una creatura davvero feroce. Non è forte fisicamente quanto un infernale, ma uno stregone saggio sa che la forza bruta non è sempre la risposta; se lo fosse, avresti scelto la via del guerriero, no?\n\nIl vilsegugio attinge al mana dei suoi nemici, sfruttandolo insieme alla sua rapidità per sopraffarli. La sua forza viene dall'arcano e dall'uso di quel potere arcano per i propri scopi.\n\nSe vuoi saperne di più sugli infernali, dovresti parlare con Magaz, di fronte a me.", "." },
  ["eb475dcc3efcf873"] = { "%s piagnucola.", "." },
  ["eb4845038002d703"] = { "Ho vissuto per un po' a ⟦Dire Maul=Maglio Infausto⟧. È stato divertente. Davvero.", "." },
  ["eb49e5daeb9dde7b"] = { "Se c'è una cosa che il tempo mi ha insegnato, è che nessun incarico è noioso. Proteggere il ⟦Thandol Span=Viadotto di Thandol⟧ avrebbe dovuto essere un compito facile. Ma con il grosso dell'esercito a combattere al fianco dell'Alleanza, qui siamo stati sopraffatti e Dun Modr è caduta.", "." },
  ["eb4d8f6bac8f0b05"] = { "Mi sento debole", "." },
  ["eb514c407c4f000f"] = { "Un gioco? Sei fuori di testa?", "." },
  ["eb5ee44c460be3f4"] = { "E sono partiti!", "." },
  ["eb66c85e529a3f70"] = { "Hai l'aria di chi torna dalle pianure. Hai notizie della Grande Madre Hawkwind?", "." },
  ["eb717850c107007c"] = { "Pare che l'ultima parte delle merci che abbiamo raccolto verrà spedita a ⟦Silithus=Silitus⟧ entro domani. E una volta fatto, qualcuno dovrà andare a suonare il gong sullo Scarab Dais, fuori da ⟦Ahn'Qiraj=Ahn'qiraj⟧, per aprire i cancelli. È allora che le nostre bende torneranno utili.", "." },
  ["eb75d69a0f9064b2"] = { "L'oscurità era calata sui miei occhi, ma tu mi hai strappato al mio sogno empio. Mi hai salvato, {name}.\n\nE ora ti supplico... di perdonarmi.", "." },
  ["eb7bac46e653a8f1"] = { "Lo scontro è cominciato. {name}, preparati a combattere!", "." },
  ["eb9b28d091f3b7af"] = { "Finalmente! Qualcuno che mi libera da questa cella!\n\nIl sommo esecutore Hadrec ci ha mandati a raccogliere informazioni sul Forte, perché si potesse elaborare un piano per rovesciare Arugal una volta per tutte.\n\nMa il vecchio mago ha molti assi nella manica, e un sigillo magico ci ha scoperti. Mi hanno gettato in questa prigione. Vincent non ha avuto la stessa fortuna.\n\nDevo tornare subito da Hadrec a fargli rapporto. Ma prima forzerò per te la serratura della porta del cortile. Forse puoi tentare la sorte contro i nemici in agguato là oltre.", "." },
  ["eba2888488f3fa5d"] = { "Spero di poter mandare qualche valoroso ad aiutare ⟦Ashenvale=Valtetra⟧ e le ⟦Sentinels=Sentinelle⟧.", "." },
  ["eba39e519075fcef"] = { "Ho dovuto andare a requisire un Abominio... un Abominio!", "." },
  ["eba5c4f5004a746f"] = { "Mai mettersi contro un ⟦Dark Iron=Ferroscuro⟧, {class}.", "." },
  ["ebae512e479941b6"] = { "Oh, be'.", "." },
  ["ebb2c1a1a3aae91c"] = { "Qualcun altro pronto a provare l'ira della ⟦Defias Brotherhood=Fratellanza dei Defias⟧?", "." },
  ["ebc66f7a1d7e7a2d"] = { "Ehi, calma, {class}, Pele'keiki pensa che tu non sapere che tutta quella roba sta andando a ⟦Silithus=Silitus⟧. A Pele'keiki hanno detto che l'ultima parte arriva là in meno di un giorno, e dopo qualche sciocco suona il gong fuori dai cancelli di ⟦Ahn'Qiraj=Ahn'qiraj⟧ per aprirli e comincia la guerra.", "." },
  ["ebc7fc5ae6bf2bbc"] = { "Salute, {class}, insegno la Conciatura a Darnassus. In cosa posso esserti utile?", "." },
  ["ebd1d03284ab9576"] = { "Carote ogni giorno per un anno se la smetti!", "." },
  ["ebd6a51523a4716c"] = { "Chi devo uccidere? Indicami solo da che parte sono, comandante.", "." },
  ["ebe5f1442d53de72"] = { "Dammi il cucciolo di ippogrifo!", "." },
